#!/usr/bin/env python3
"""Review analytic native identities, explicitly separating off-constraint probes."""
import argparse,csv,hashlib,json,math
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('csv',type=Path);p.add_argument('output',type=Path);a=p.parse_args();rows=[{k:float(v) for k,v in x.items()} for x in csv.DictReader(a.csv.open())];assert len(rows)==72 and all(math.isfinite(v) for x in rows for v in x.values());on=[x for x in rows if x['gauge_variant']<2];off=[x for x in rows if x['gauge_variant']==2];constraint=['H','M_conformal','Z_conformal','Theta','Theta_dot','Z_dot_x','Z_dot_y','Z_dot_z'];maxima={k:max(abs(x[k]) for x in on) for k in constraint};identity={k:max(abs(x[k]) for x in rows) for k in ['Theta_identity_error','Z_identity_error_max','connection_variation_error1','connection_variation_error2']};nontrivial=max(x['Gamma_dot_max'] for x in rows)>1e-6 and max(abs(x['H']) for x in off)>1e-6;mass=[x for x in on if x['mass']==.5 and x['gauge_variant']==0 and x['direction']==0];r=dict(passed=max(maxima.values())<=1e-8 and max(identity.values())<=1e-7 and nontrivial,on_constraint_samples=len(on),off_constraint_samples=len(off),on_constraint_maxima=maxima,identity_and_variation_maxima=identity,nontrivial_probes=nontrivial,maximum_off_constraint_H=max(abs(x['H']) for x in off),maximum_off_constraint_M=max(abs(x['M_conformal']) for x in off),mass_scalar_Sommerfeld_residuals=[dict(radius=x['radius'],Omega=x['Omega'],chi_dot=x['chi_dot'],chi_deviation=x['chi_deviation'],residual=x['naive_chi_Sommerfeld']) for x in mass],scope='Exact analytic jets and native instantaneous RHS. Verifies Theta=Z=0 => Theta_dot=alpha H/(2Omega), Zdot_i=alpha M_i/Omega in tested states, including deliberate H/M violations. Does not derive full off-manifold subsidiary system or a nonlinear constraint-preserving boundary estimate. Scalar chi residual is a counterexample to arbitrary homogeneous component data, not proof of current ghost-closure mass loss.',csv_sha256=hashlib.sha256(a.csv.read_bytes()).hexdigest(),script_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest());a.output.write_text(json.dumps(r,indent=2)+'\n');print(r)
